4	// Pantry allergen tags (team decision 2026-11-08): the provider's or user's tags UNION whatever
5	// Hang's keyword map (server/diet/check.ts, read-only) finds in the item's name. Over-tagging only
6	// makes AI substitutions stricter, which is the safe direction.
7	
8	export const ALL_ALLERGENS = Object.keys(ALLERGEN_KEYWORDS) as Allergen[];
9	
10	export function isAllergen(x: unknown): x is Allergen {
11	  return typeof x === 'string' && Object.hasOwn(ALLERGEN_KEYWORDS, x);
12	}
