14	/** Allergens whose keywords appear in any of `texts` (e.g. name and brand). */
15	export function detectAllergens(texts: Array<string | null | undefined>): Allergen[] {
16	  const lines = texts.filter((t): t is string => typeof t === 'string' && t.trim() !== '');
17	  if (lines.length === 0) return [];
18	  const found = new Set<Allergen>();
19	  for (const v of checkDiet(lines, { diets: [], allergens: ALL_ALLERGENS }).violations) {
20	    if (isAllergen(v.rule)) found.add(v.rule);
21	  }
22	  return ALL_ALLERGENS.filter((a) => found.has(a));
23	}
24	
25	/** Union of given tags and name-detected tags, deduplicated, in enum order. */
26	export function pantryAllergenTags(given: readonly Allergen[] | null | undefined, name: string): Allergen[] {
27	  const set = new Set<Allergen>([...(given ?? []).filter(isAllergen), ...detectAllergens([name])]);
28	  return ALL_ALLERGENS.filter((a) => set.has(a));
29	}
